export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / (1000 * 60 * 60 * 24))
}

export function beginningOfDay(date) {
  // Compare local calendar days on a UTC scale so 23/25-hour DST days still count as one day.
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function parseLocalTime(timestamp) {
  // A date-only value is a calendar day, not midnight UTC (which can be the previous local day).
  return new Date(/^\d{4}-\d{2}-\d{2}$/.test(timestamp) ? `${timestamp}T00:00:00` : timestamp)
}

export function formatLocalTime(date, format = "relative", now = new Date()) {
  if (!Number.isNaN(date.getTime())) {
    if (format === "relative") {
      return formatRelativeTime(date, now)
    } else {
      return new Intl.DateTimeFormat("en-US", formats[format]).format(date)
    }
  }
}

const formats = {
  time: { hour: "numeric", minute: "2-digit" },
  date: { month: "short", day: "numeric" },
  "full-date": { month: "short", day: "numeric", year: "numeric" },
  "long-date": { weekday: "long", month: "long", day: "numeric" },
  datetime: { month: "numeric", day: "numeric", year: "2-digit", hour: "numeric", minute: "2-digit" },
  title: { weekday: "long", month: "long", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit", timeZoneName: "short" }
}

function formatRelativeTime(date, now) {
  const days = signedDifferenceInDays(now, date)

  if (days === 0) {
    return formatLocalTime(date, "time")
  } else if (days === -1) {
    return "yesterday"
  } else if (days === 1) {
    return "tomorrow"
  } else if (days > 1) {
    return `in ${days} days`
  } else if (days > -7) {
    return `${-days} days ago`
  } else {
    return formatLocalTime(date, date.getFullYear() === now.getFullYear() ? "date" : "full-date")
  }
}
